export function parseFlag(value: unknown, defaultValue = false): boolean {
  if (value === undefined || value === null) return defaultValue;
  if (typeof value === "boolean") return value;
  if (typeof value === "string") {
    switch (value.trim().toLowerCase()) {
      case "true":
      case "1":
      case "yes":
      case "on":
        return true;
      case "false":
      case "0":
      case "no":
      case "off":
        return false;
    }
  }
  throw new TypeError("Invalid feature flag value");
}

import test from "node:test";
import assert from "node:assert/strict";
import { parseFlag } from "../src/config.ts";
import { DocumentService } from "../src/service.ts";

const accepted = [
  [true, true], [false, false],
  ...["true", "1", "yes", "on"].flatMap(value =>
    [value, ` \t${value.toUpperCase()}\n`].map(input => [input, true])),
  ...["false", "0", "no", "off"].flatMap(value =>
    [value, ` \t${value.toUpperCase()}\n`].map(input => [input, false])),
];
const rejected = [
  0, 1, -1, NaN, Infinity, "", " \t\n", "enabled", "truthy", "2",
  "true false", [], ["true"], {}, { value: true }, new Boolean(false),
  new String("true"), 1n, Symbol("true"), () => true,
];

test("parseFlag accepts only booleans and supported string values", () => {
  for (const [value, expected] of accepted) {
    assert.equal(parseFlag(value), expected);
    assert.equal(parseFlag(value, !expected), expected);
  }
  for (const value of rejected) {
    assert.throws(() => parseFlag(value), TypeError);
    assert.throws(() => parseFlag(value, true), TypeError);
  }
});

test("parseFlag uses the default only for missing or null values", () => {
  assert.equal(parseFlag(), false);
  for (const value of [undefined, null]) {
    assert.equal(parseFlag(value), false);
    assert.equal(parseFlag(value, true), true);
    assert.equal(parseFlag(value, false), false);
  }
});

test("DocumentService feature flags use strict parsing", () => {
  const service = new DocumentService();
  for (const [value, expected] of accepted) {
    assert.equal(service.featureEnabled(value), expected);
  }
  assert.equal(service.featureEnabled(), false);
  assert.equal(service.featureEnabled(null), false);
  for (const value of rejected) {
    assert.throws(() => service.featureEnabled(value), TypeError);
  }
});

